// One item per outbound-enabled product. The endpoint returns
// {products:[...], count:n}; without this the HTTP node downstream would see a
// single item and trigger exactly one product.
const body = $input.first().json || {};
const products = Array.isArray(body.products) ? body.products : [];
if (!products.length) {
  // Emit a marker rather than nothing, so the digest can say "none enabled"
  // instead of the workflow ending silently with no email at all.
  return [{ json: { __none: true, count: 0 } }];
}
return products.map((p) => ({ json: p }));

// A QUEUED receipt, not a result. Each run takes hours; the Sunday 20:00
// Weekly Digest reports what completed. Saying "queued" here keeps the two
// claims from being confused.
const items = $input.all();
const lines = [];
let queued = 0, refused = 0, failed = 0;
let budgetLine = null;

for (const it of items) {
  const j = it.json || {};
  if (j.__none) {
    lines.push('No products have outbound_enabled = true. Nothing was queued.');
    continue;
  }
  // continueRegularOutput puts a failed request's payload under .error
  const err = j.error || null;
  const detail = (err && err.detail) || j.detail || null;

  if (detail && detail.error === 'brave_budget_exhausted') {
    refused++;
    const b = detail.budget || {};
    lines.push('REFUSED (Brave budget): ' + (b.reason || 'budget exhausted'));
  } else if (j.run_id) {
    queued++;
    lines.push('queued run ' + j.run_id + ' (status ' + (j.status || '?') + ')');
    if (j.brave_budget) budgetLine = j.brave_budget;
  } else if (err) {
    failed++;
    lines.push('FAILED to queue: ' + (err.message || JSON.stringify(err)).slice(0, 180));
  } else {
    failed++;
    lines.push('FAILED to queue: unrecognised response ' + JSON.stringify(j).slice(0, 180));
  }
}

const header = queued + ' run(s) queued, ' + refused + ' refused on budget, ' + failed + ' failed.';
const body = [header, ''].concat(lines);
if (budgetLine) {
  body.push('');
  body.push('Brave budget: ' + budgetLine.used + '/' + budgetLine.cap +
            ' used (' + budgetLine.percent_used + '%), stop threshold ' +
            budgetLine.threshold + ', ' + budgetLine.remaining_to_threshold +
            ' left before it.');
}
body.push('');
body.push('These runs take hours. The Sunday 20:00 Weekly Digest reports what completed.');

return [{ json: { subject: 'Lead Finder - runs queued', body: body.join('\n') } }];
